  ad_group_criterion_listing_group_case_value_product_condition_condition STRING OPTIONS(description="Value of the condition."),
  ad_group_criterion_listing_group_case_value_product_custom_attribute_index STRING OPTIONS(description="Indicates the index of the custom attribute."),
  ad_group_criterion_listing_group_case_value_product_custom_attribute_value STRING OPTIONS(description="String value of the product custom attribute."),
